def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find full separator lines: a line is a divider when it is uniform
    # and its color occurs in every row/column at that position.
    row_divs = [r for r in range(h) if len(set(grid[r])) == 1]
    col_divs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # The divider color is the color shared by the full separator lines.
    candidates = []
    for r in row_divs:
        candidates.append(grid[r][0])
    for c in col_divs:
        candidates.append(grid[0][c])
    if not candidates:
        return [row[:] for row in grid]
    color = max(set(candidates), key=candidates.count)

    row_divs = [r for r in row_divs if grid[r][0] == color]
    col_divs = [c for c in col_divs if all(grid[r][c] == color for r in range(h))]

    def chunks(n, divs):
        bounds = [0]
        for d in divs:
            bounds.extend((d, d + 1))
        bounds.append(n)
        return [(bounds[i], bounds[i + 1]) for i in range(0, len(bounds) - 1, 2)
                if bounds[i] < bounds[i + 1]]

    row_chunks = chunks(h, row_divs)
    col_chunks = chunks(w, col_divs)

    # Choose the non-divider region containing the most pattern cells as source.
    regions = [(r0, r1, c0, c1)
               for r0, r1 in row_chunks for c0, c1 in col_chunks]
    sr0, sr1, sc0, sc1 = max(
        regions,
        key=lambda q: sum(grid[r][c] != color
                          for r in range(q[0], q[1])
                          for c in range(q[2], q[3]))
    )
    tile = [grid[r][sc0:sc1] for r in range(sr0, sr1)]
    th, tw = len(tile), len(tile[0])

    out = [row[:] for row in grid]
    for r0, r1 in row_chunks:
        for c0, c1 in col_chunks:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = tile[(r - r0) % th][(c - c0) % tw]
    return out
